const fs = require('fs');
const path = require('path');
const outDir = path.join($json.tender_root, '05_RFI');
const rfiCount = (() => { try { return JSON.parse($json.stdout || '{}').rfi_count || 0; } catch { return 0; }})();
fs.writeFileSync(path.join(outDir, 'rfi_cover_note.txt'), `Please review attached draft RFIs for ${$json.tender_id}. Total RFIs: ${rfiCount}.`, 'utf-8');
return [{json: {...$json, rfi_count: rfiCount}}];
